from pathlib import Path
import ast,json
BASE=Path('英文小论文/code/original_stem12_monitor_20261011_v1')
OUT=Path('英文小论文/code/stem_component12_monitor_20261011_v1')
assert not OUT.exists();OUT.mkdir()
def save(n,s): (OUT/n).write_text(s,encoding='utf8',newline='\n')
def change(s,a,b):
    assert a in s,a
    return s.replace(a,b)
def common(s):
    return s.replace('original_stem12_monitor_20261011_v1','stem_component12_monitor_20261011_v1').replace('original_stem12_20261011_v1','stem_component12_20261011_v1').replace('original_stem_fixed12','stem_component_fixed12').replace('original_stem12_terminal_v1','stem_component12_terminal_v1').replace('original_stem12_training_v1','stem_component12_training_v1').replace('original_stem12_closeout_v1','stem_component12_closeout_v1').replace('PASS_ORIGINAL_STEM_FIXED12','PASS_STEM_COMPONENT_FIXED12')
s=common((BASE/'verify_terminal_local.py').read_text(encoding='utf8'))
s=change(s,"    assert identity['arm'] == plan['arm'] == 'original_stem'","    assert identity['arm'] == plan['arm'] and identity['arm'] in read(CORE/'training_protocol.json')['execution_allowlist']")
s=change(s,"    cfg['OriginalStemDEIM']=cfg.pop('ResidualGeometryDEIM')","    cfg['OriginalStemDEIM']=cfg.pop('ResidualGeometryDEIM')\n    cfg['OriginalStemDEIM']['control']=plan['arm']")
s=change(s,"    assert saved['seed'] == identity['seed'] and saved['arm'] == 'original_stem'","    assert saved['seed'] == identity['seed'] and saved['arm'] == identity['arm']")
s=change(s,"    init=runtime['initialization']","    preflight=read(screen/'preflight.json')\n    assert preflight['status']=='CONTROL_SHAPE_GRADIENT_AND_INITIALIZATION_PASS'\n    assert preflight['seed']==identity['seed'] and preflight['arm']==identity['arm']\n    assert preflight['all_initial_stem_tensors_match_full'] is True\n    assert preflight['full_forward_exactly_original'] is True\n    assert preflight['all_stem_trainable_tensors_receive_finite_gradients'] is True\n    assert preflight['full_model_forwards']==preflight['optimizer_updates']==preflight['baseline_forwards']==0\n    assert preflight['shapes']==[[4,16,160,160],[4,16,208,208]]\n    init=runtime['initialization']")
s=change(s,"    assert init['parameters']==10237322", "    assert preflight['initialization']==init\n    assert init['parameters']==10237322")
s=change(s,"        archive_sha256=sha(archive),", "        downloaded_packet=str(destination), archive_sha256=sha(archive),")
save('verify_terminal_local.py',s)
s=common((BASE/'decide_fixed12.py').read_text(encoding='utf8'))
s=change(s,"    reports.sort(key=lambda x: x['identity']['seed'])", "    reports.sort(key=lambda x: x['identity']['seed'])\n    arms={r['identity']['arm'] for r in reports}\n    assert len(arms)==1 and arms<=set(p['arms'])\n    arm=next(iter(arms))")
s=change(s,"        assert r['identity']['arm'] == 'original_stem'", "        assert r['identity']['arm'] == arm")
s=s.replace("'RETAIN_ORIGINAL_STEM_FOR_MECHANISM_FOLLOWUP' if passed else 'REJECT_ORIGINAL_STEM_NO_EXTENSION_OR_RETRY'", "'CONTROL_PASSES_BASE12' if passed else 'CONTROL_DOES_NOT_PASS_BASE12'")
s=change(s,"        both_seeds_passed=passed", "        arm=arm,both_seeds_passed=passed")
save('decide_fixed12.py',s)
s=common((BASE/'validate_cpu.py').read_text(encoding='utf8'))
save('validate_cpu.py',s)
s=common((BASE/'compare_live_history.py').read_text(encoding='utf8'))
save('compare_live_history.py',s)
s=common((BASE/'register_protocol.py').read_text(encoding='utf8'))
s=s.replace('len(files)==23','len(files)==25')
s=change(s,"'validate_cpu.py','compare_live_history.py')", "'validate_cpu.py','compare_live_history.py','compare_components.py')")
s=change(s,"    core_files_sha256=files", "    arms=list(read(CORE/'training_protocol.json')['execution_allowlist']),core_files_sha256=files")
s=change(s,"    notes=['Only backbone.stem is replaced; native matching, criterion and augmentation remain.'", "    notes=['One changed operation per control within the original Stem; all parameters retained.'")
save('register_protocol.py',s)
save('compare_components.py',Path('outputs/stem_component12_20261011_v1/compare_components_source.py').read_text(encoding='utf8'))
for p in OUT.glob('*.py'): ast.parse(p.read_text(encoding='utf8'))
print(json.dumps(dict(directory=str(OUT),files=len(list(OUT.glob('*.py'))))))
